function guide(){
 document.title="Mid & end game guide · Linggango Relic Wiki";
 const SEC=[["g1","Act axis"],["g2","L2 Hostility"],["g3","Goety"],["g4","Linggango Tweaks — hidden rules"],["g5","Tech & Magic"],["g6","Keeper unlocks"],["g7","L2 trait hunting"],["g8","Boss route"]];
 const traits=[...new Set(L2D.flatMap(x=>x.tr))].sort();
 const trRows=traits.map(t=>`<tr><td><b>${t.replace(/_/g," ")}</b></td><td>${LURE[t]?esc(LURE[t]):"<span class='note'>no lure</span>"}</td><td>${L2D.filter(x=>x.tr.includes(t)).map(x=>{const u=usedBy(x.item);return `${x.n}× ${esc(nmI(x.item))} <span class="tg">${CHN[x.charm]} · ${Math.round(x.ch*100)}%${x.rb?` +${Math.round(x.rb*100)}%/level`:""}</span>${x.ml.length?" <span class='tg'>mob level ≥100</span>":""}${u.length?`<br><span class="note">used by: ${u.slice(0,6).map(d=>`<a href="#i${d.ix}">${esc(d.n)}</a>`).join(", ")}${u.length>6?` +${u.length-6}`:""}</span>`:""}`}).join("<br>")}</td></tr>`).join("");
 let last=null,bossRows="";
 for(const [n,a,c,note,lo] of BOSSR){if(a!==last){bossRows+=`<tr class="ab"><td colspan="3">${actL(a)}</td></tr>`;last=a}
  const L=lo.slice(0,6).map(id=>{const u=usedBy(id);return esc(nmI(id))+(u.length?` <span class="note">→ ${u.slice(0,3).map(d=>`<a href="#i${d.ix}">${esc(d.n)}</a>`).join(", ")}${u.length>3?` +${u.length-3}`:""}</span>`:"")}).join("<br>");
  bossRows+=`<tr><td><b>${esc(n)}</b>${note?`<br><span class="note">${esc(note)}</span>`:""}</td><td class="num">${c}</td><td>${L||'<span class="note">—</span>'}</td></tr>`}
 el("main").innerHTML=`${crumb("Guide")}<h1>Mid &amp; end game guide</h1>
<p class="lede">Ties curios to the Act progression, L2 Hostility, Goety, Linggango Tweaks and the Tech/Magic mods. Each entry carries a confidence label.</p>
<div class="legend">${cf("ok")}${cf("code")}${cf("q")}</div>
<div class="toc"><b>CONTENTS</b><ol>${SEC.map(([id,t])=>`<li><a href="#guide" data-go="${id}">${t}</a></li>`).join("")}</ol></div>
${sec("g1","1. Act axis",`<p class="note">The Keeper defeated at the end of Act N opens the gate for Act N+1. Acts IX–XII are still locked in the quest book, so their data comes from code/config only.</p>${tbl(["Act","Keeper","Weakness","Opens gate","Looting Charm","Curios / notes","Confidence"],ACTS.map(a=>`<tr><td class="num"><b>${a[0]}</b></td><td>${a[1]}</td><td>${a[2]}</td><td>${a[3]}</td><td>${a[4]}</td><td>${a[5]}</td><td>${CF[a[6]][0]}</td></tr>`).join(""))}`)}
${sec("g2","2. L2 Hostility — Looting Charms",`<p class="lede"><span class="badge new">IMPORTANT</span>A charm must be <b>worn in a curio slot</b> for its drops to appear (disableHostilityLootCurioRequirement = false). Trait-added drops are still cut by Lean Drops. Chance = chance + trait level × rankBonus, and each item in a stack rolls separately.</p>${tbl(["Charm","Unlocked","Drops","Worth farming"],L2.map(r=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td class="num">${r[2]}</td><td>${r[3]}</td></tr>`).join(""))}<p class="note">The original L2 Complements methods still work: Hard Ice = kill Drowned with Powder Snow; Force Field = finish the Wither with an arrow. These materials feed the Study Lectern (parry/dodge milestones are cumulative and never consumed).</p>`)}
${sec("g3","3. Goety",tbl(["Item","Recipe / source","Notes"],`<tr><td><b>Scroll of Blessing</b></td><td>Darkest Scroll + Heart of the Earth + nautilus shell + sunflower + feather + ink sac + gold</td><td>+1 Luck stat; each Luck point gives +2% damage, +2.5% attack speed, +2% dodge (dodge capped at 15%). This dodge does not trigger Brutality anklets.</td></tr>
<tr><td><b>Potion of Transformation</b></td><td>Ritual sacrificing a villager; Unholy Blood, totem, end crystal, enchanted golden apple, echo shard</td><td>Used for Dimensional Will.</td></tr>
<tr><td><b>Luck brew</b></td><td>Goety brewing</td><td>Raises the Luck <i>effect level</i> (doesn't stack), unlike the Luck <i>stat</i> (stacks).</td></tr>`))}
${sec("g4","4. Linggango Tweaks — hidden rules",tbl(["Rule","Details"],`<tr><td>Damage taken floor</td><td>13% of each hit pierces all damage reduction; dodge / parry / i-frames cancel the whole hit.</td></tr>
<tr><td>Per-hit cap</td><td>A hit from an enemy takes at most 50% of max health → Ring of Life (80%) is nearly redundant.</td></tr>
<tr><td>Boss intake</td><td>93 bosses (nightmare_bosses, not the Ender Dragon): at most 1/30 health per second and 10% per hit until their first defeat; Nightmare Altar bosses always keep the cap.</td></tr>
<tr><td>Hardmode</td><td>After the Ender Dragon: ×2.1 mob health and damage (except the Warden).</td></tr>
<tr><td>Ladder</td><td>200 × (rung/10)³ over 10 Keepers; Cataclysm doesn't count; Sanghor 69 → 102.</td></tr>
<tr><td>No Cheese / Lean Drops</td><td>Run on LivingDropsEvent; Drygmy and Hostile Neural Networks escape both. FakePlayer kills lose drops.</td></tr>
<tr><td>Horrible Scavenger</td><td>Every chest stack ×0.2 (randomly rounded); 22 loot_protected items are exempt.</td></tr>`)+`<h3 style="margin-top:16px">Weapon damage floor calculator</h3><div class="craft" style="gap:10px">
<label>Base damage <input id="gb" type="number" value="10" style="width:70px"></label><label>Somber Stones <input id="gs" type="number" value="0" min="0" max="20" style="width:60px"></label>
<label>Attack speed <input id="gp" type="number" step="0.1" value="1.6" style="width:60px"></label><label>Tier <select id="gt" style="width:auto">${Object.keys(TF).map(k=>`<option>${k}</option>`).join("")}</select></label>
<div id="go" class="st"></div></div><p class="note">Formula: effective floor = min(floor, (floor+1) × 1.8 / speed − 1). Somber Stones (+0.5 each, max +10) are added before comparing to the floor. Exceptions: Royal Guardian Sword 70, Amaterasu/Tsukuyomi 17.</p>`)}
${sec("g5","5. Tech &amp; Magic for curios",tbl(["Mod","What to know","Confidence"],[["Hostile Neural Networks","Legit drop farming, escapes No Cheese and Lean Drops."],["Kill machines (FakePlayer)","Not a real player's kill credit → lose Terra Curio drops and drops kept by No Cheese."],["Powah / AE2","Powah batteries and AE2 terminals fit the universal Curio slot (it also takes items from other slots)."],["AE2 Certus Quartz Pickaxe","Not gated, mining power 2."],["Blood Magic","Socketed Upgrade Tome +1 Living Armour Socket each, up to 5; holds sigils, Tartaric Gems, Training Bracelet."],["Ars Additions","+3 Charm (Charm base 6 = 3 + 3)."],["Enigmatic Legacy","The Curses branch unlocks many Curses-only items (Astral Fruit +1 Ring, Ichor Bottle +1 Charm, Enchanter's Pearl…). Amulet of Ascension = Enigmatic Amulet + Heart of the Cosmos."],["Enigmatic Dice","Ring of Agility: dodge = 1 − 0.99^(speed × 100), up to 30%."]].map(([a,b])=>`<tr><td>${a}</td><td>${b}</td><td>🔍</td></tr>`).join("")))}
${sec("g6","6. Keeper unlocks (pack config)",`<p class="lede">Per <code>[progression_gates]</code> in <code>linggango_tweaks-common.toml</code>: items in the <code>linggango_tweaks:gated/&lt;tier&gt;</code> tag can't be taken out of a crafting station, placed, used or worn until you have the Keeper's advancement. ${D.filter(d=>d.gk).length} curios in this wiki are gated this way (🔒 badge). These quest chapters also stay greyed out until the gate opens.</p>${tbl(["Opens at","Defeat Keeper","Chapters / mods unlocked","Gated curios"],CHAP.map(([a,t])=>`<tr><td class="num"><b>${actL(a)}</b></td><td>${GK[a]}</td><td>${esc(t)}</td><td class="num">${D.filter(d=>d.gk===a).length}</td></tr>`).join(""))}`)}
${sec("g7","7. L2 trait hunting (Linggango Tweaks)",`<p class="lede">Mobs with L2 traits drop <b>Hostile Remnants</b> (1 per 2 trait levels, rounded up). 9 Remnants = 1 <b>Hostile Core</b>. Core + the ingredient below = 2 <b>Trait Lures</b>; each Lure summons 3 mobs with that trait. Burning a Core (L2 Complements, 1/3 chance) gives Hostility Essence, needed for high-tier lures. Burning an L2 trait item gives 2 Cores.</p><p class="note">Mastery: each kill gives every trait points equal to its level; 30 / 120 / 400 points grant −5/10/15% damage taken from and +5/10/15% damage to mobs with that trait. Trait drops only appear when a player kills the mob while wearing a Looting Charm of the right tier in a curio slot: Unpolished (after Arion, Act III), Magical (Act V), Chaotic (Act VII), Miraculous (Act X). Chance = chance + trait level × rankBonus.</p>${tbl(["Trait","Lure (Core + …)","Drops (charm needed · chance) and curios that use them"],trRows)}`)}
${sec("g8","8. Boss route and loot use",`<p class="lede">Suggested order slotting side bosses between the Keepers. ✓ = pack stats (<code>entitybalance.json</code>) compared to the Keepers; 🔍 = inferred from dimension or config; ❓ = estimated from the mod's base difficulty, untested in the pack. The last column lists the boss's own drops and the curios that use them.</p>${tbl(["Boss","Confidence","Loot worth keeping → curios"],bossRows)}
<h3 style="margin-top:16px">Using loot (Linggango Tweaks config rules)</h3><ul class="note" style="font-size:13px;line-height:1.6">
<li><b>First fight is capped:</b> a boss loses at most 1/30 of its health per second and 10% per hit (so the fight lasts at least 30 s) until you beat it once. After that your hits ignore the cap, so re-farming is fast.</li>
<li><b>Nightmare Altar:</b> re-summons a defeated boss. Each L2 trait item placed on the altar (up to 8) adds 25 Hostility levels and one more full loot roll. Altar bosses always keep the damage cap, so this is how to multiply rare drops up to ×9, like Dragon Band, Angel Feather, Gob's Gilded Hat.</li>
<li><b>Group fights:</b> every player within 64 blocks when the boss dies gets the kill, Keeper milestones included.</li>
<li><b>Multi-phase bosses:</b> Arion, Bringer of Doom, Sanghor, Morphegor and Draugr have a second phase; beating phase two counts as the kill.</li>
<li><b>Kill by hand:</b> Terra Curio drops and L2 trait drops only fall when a real player lands the kill. Kill machines (FakePlayer) lose them.</li>
<li><b>Suggested farm order:</b> get the Unpolished Charm after Arion and hunt Gravity/Moonwalk traits for dragon's breath; after Zoranth fight Super Sniffer and the Shadow Wizards (Antiprism opens Brutality's Unbridled Rage branch); after the Elvenite Paladin fight Gob and the Trial Guardian (the Smithing Template opens Brutality's math group); leave Virtue and Ultra Sniffer until after The Calamities.</li></ul>`)}`;
 ["gb","gs","gp","gt"].forEach(i=>el(i).addEventListener("input",gcalc));gcalc();
}

